import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`freelancer-upwork`,heroTitle:`Win freelance gigs in minutes`,heroSubtitle:`Perplexity Computer researches the client, drafts a tailored proposal and cover letter, and builds your SOW automatically.`,inputUrlCta:`Write my proposal`,inputUrlPlaceholder:`Paste job post URL`,inputUrlPrefill:`Go to {url} and analyze the job posting or portfolio page in detail. Then do the following: 1) Research the client or company — find their website, recent news, team members, hiring patterns, past freelancer reviews, and any public information about their business goals. 2) Draft a tailored proposal and cover letter that references specific client details — their company name, recent projects, pain points mentioned in the job post, and why my skills are the right fit. Make the tone confident but personable. 3) Generate a discovery-call prep document with 8-10 smart questions to ask the client — covering scope, timeline, decision-making process, budget expectations, success metrics, and past experiences with freelancers. 4) Build a statement of work (SOW) template with clearly defined scope, deliverables, milestones, timeline, revision policy, and a suggested pricing structure with hourly and project-based options. Format everything cleanly with headers and sections so I can copy, customize, and send within 5 minutes.`,heroOverlaySteps:[`Researching the client's company, team, and hiring patterns`,`Drafting a tailored proposal and cover letter with client specifics`,`Building a discovery-call prep doc with strategic questions`,`Proposal, cover letter, prep doc, and SOW ready to send`],generatingSteps:[`Analyzing the job post to extract client details, scope, and requirements`,`Designing an agent to research the client and draft a personalized proposal`,`Configuring cover letter generation, discovery-call prep, and SOW templates`,`Setting up your complete freelance proposal pipeline`],featureSectionTitle:`From job post to winning proposal`,featureCardTitles:[`The best model for every task`,`Connects to your freelance stack`],featureCardDescriptions:[`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,`Google Docs, Google Drive, Notion, Gmail, Google Sheets — Computer delivers your proposals and SOWs straight into the tools you already use.`,`Tailored cover letters. Client research briefs. Discovery-call question lists. Scoped SOW templates with pricing. Everything personalized to the gig.`],capabilitySectionTitle:`Your proposal team, on autopilot`,capabilitySectionSubtitle:`Describe the gig, step away, come back to a ready-to-send proposal package.`,capabilityCards:[{title:`Client Research`,description:`Computer can research the client's company, recent news, team structure, and hiring patterns so your proposal references specifics they care about.`},{title:`Proposal Drafting`,description:`Computer can write a tailored proposal and cover letter that mirrors the job post language, addresses pain points, and positions your expertise.`},{title:`Discovery Prep`,description:`Computer can generate a call prep doc with strategic questions, talking points, and client-specific insights so you walk in prepared.`},{title:`Connect Your Tools`,description:`Computer can export to Google Docs, Notion, Gmail, and Google Drive — build workflows across your entire freelance stack.`},{title:`Remember & Improve`,description:`Computer can remember your portfolio, past proposals, and win rates across sessions so every new pitch gets sharper over time.`},{title:`Monitor & Alert`,description:`Computer can scan job boards for new gigs matching your skills and alert you when high-fit opportunities appear.`}]});export{t as default};
